/*
 * The Apple boot screen of the retail firmware, exactly as the firmware's
 * boot graphics carry it: 320x240 RGB565, little-endian, row-major.
 *
 * This is the firmware's own asset, not a reconstruction: "apple-boot.rgb565"
 * from the retail 2.0.5 boot graphics, quantised to 5-6-5 with serpentine
 * Floyd-Steinberg dithering (source sha256 97e049729437affb...).  The panel
 * model copies it straight into image memory, so what the page shows on the
 * boot screen is byte-for-byte the firmware's own picture -- no
 * re-quantising and no dither of ours.
 */
